const reconciliationCounterpartyInvoices = `-- name: ReconciliationCounterpartyInvoices :many

SELECT x.tax_id::text AS tax_id,
       MAX(x.name)::text AS name,
       COALESCE(SUM(x.signed_payable), 0)::numeric AS invoice_balance,
       COALESCE(SUM(x.net) FILTER (WHERE x.direction = 'incoming' AND x.period = $1::text), 0)::numeric AS ba_amount,
       COUNT(*) FILTER (WHERE x.direction = 'incoming' AND x.period = $1::text)::int AS ba_count,
       COALESCE(SUM(x.net) FILTER (WHERE x.direction = 'outgoing' AND x.period = $1::text), 0)::numeric AS bs_amount,
       COUNT(*) FILTER (WHERE x.direction = 'outgoing' AND x.period = $1::text)::int AS bs_count
FROM (
    SELECT COALESCE(NULLIF(i.customer_tax_number, ''), NULLIF(i.customer_identity_number, '')) AS tax_id,
           COALESCE(i.customer_name, '') AS name,
           i.direction, i.period,
           (CASE WHEN i.direction = 'outgoing' THEN 1 ELSE -1 END) *
             (CASE WHEN i.currency = 'TRY' THEN i.payable_amount
                   ELSE COALESCE(i.payable_amount_try, i.payable_amount * COALESCE(i.exchange_rate, 0)) END) AS signed_payable,
           CASE WHEN i.currency = 'TRY' THEN i.tax_exclusive_amount
                ELSE i.tax_exclusive_amount * COALESCE(i.exchange_rate, 0) END AS net
    FROM invoices i
    WHERE i.taxpayer_id = $2 AND i.status_normalized = 'active' AND i.issue_date <= $3::date
) x
WHERE x.tax_id IS NOT NULL AND x.tax_id ~ '^[0-9]{10,11}$'
GROUP BY x.tax_id
ORDER BY x.tax_id
`

type ReconciliationCounterpartyInvoicesParams struct {
	Period     string      `json:"period"`
	TaxpayerID int64       `json:"taxpayer_id"`
	DateTo     pgtype.Date `json:"date_to"`
}

type ReconciliationCounterpartyInvoicesRow struct {
	TaxID          string         `json:"tax_id"`
	Name           string         `json:"name"`
	InvoiceBalance pgtype.Numeric `json:"invoice_balance"`
	BaAmount       pgtype.Numeric `json:"ba_amount"`
	BaCount        int32          `json:"ba_count"`
	BsAmount       pgtype.Numeric `json:"bs_amount"`
	BsCount        int32          `json:"bs_count"`
}

// Cari mutabakat, BA/BS ve mutabakat mektupları (#389).
// Karşı firma bazında: dönem sonuna kadarki faturalardan işaretli bakiye
// (satış +, alış −; TL) ve dönemin BA (alış) / BS (satış) KDV hariç
// tutarı ile belge sayısı.
func (q *Queries) ReconciliationCounterpartyInvoices(ctx context.Context, arg ReconciliationCounterpartyInvoicesParams) ([]ReconciliationCounterpartyInvoicesRow, error) {
	rows, err := q.db.Query(ctx, reconciliationCounterpartyInvoices, arg.Period, arg.TaxpayerID, arg.DateTo)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReconciliationCounterpartyInvoicesRow{}
	for rows.Next() {
		var i ReconciliationCounterpartyInvoicesRow
		if err := rows.Scan(
			&i.TaxID,
			&i.Name,
			&i.InvoiceBalance,
			&i.BaAmount,
			&i.BaCount,
			&i.BsAmount,
			&i.BsCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const reconciliationCounterpartyPayments = `-- name: ReconciliationCounterpartyPayments :many
SELECT COALESCE(NULLIF(i.customer_tax_number, ''), NULLIF(i.customer_identity_number, ''))::text AS tax_id,
       COALESCE(SUM(CASE WHEN t.debit_credit = 'A' THEN -m.amount ELSE m.amount END), 0)::numeric AS paid
FROM bank_transaction_matches m
JOIN bank_transactions t ON t.taxpayer_id = m.taxpayer_id AND t.id = m.bank_transaction_id
JOIN invoices i ON i.taxpayer_id = m.taxpayer_id AND i.id = m.target_id
WHERE m.taxpayer_id = $1 AND t.taxpayer_id = $1 AND i.taxpayer_id = $1
  AND m.target_type = 'invoice' AND t.transaction_date <= $2::date AND NOT t.is_cancelled
  AND t.currency = 'TRY'
  AND COALESCE(NULLIF(i.customer_tax_number, ''), NULLIF(i.customer_identity_number, '')) IS NOT NULL
GROUP BY 1
`

type ReconciliationCounterpartyPaymentsParams struct {
	TaxpayerID int64       `json:"taxpayer_id"`
	DateTo     pgtype.Date `json:"date_to"`
}

type ReconciliationCounterpartyPaymentsRow struct {
	TaxID string         `json:"tax_id"`
	Paid  pgtype.Numeric `json:"paid"`
}

// Faturalara eşleşmiş banka hareketleri, karşı firma bazında işaretli
// (gelen para alacağı azaltır −, giden para borcu azaltır +).
func (q *Queries) ReconciliationCounterpartyPayments(ctx context.Context, arg ReconciliationCounterpartyPaymentsParams) ([]ReconciliationCounterpartyPaymentsRow, error) {
	rows, err := q.db.Query(ctx, reconciliationCounterpartyPayments, arg.TaxpayerID, arg.DateTo)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReconciliationCounterpartyPaymentsRow{}
	for rows.Next() {
		var i ReconciliationCounterpartyPaymentsRow
		if err := rows.Scan(&i.TaxID, &i.Paid); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

